namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public required string Code { get; set; }
    public required string Title { get; set; }
    public required string Description { get; set; }
    public int Credits { get; set; }
    public required string Schedule { get; set; }
    public required string InstructorName { get; set; }
    public required string InstructorBio { get; set; }
    public required string DepartmentCode { get; set; }
    public bool IsFeatured { get; set; }
}

public class Department
{
    public required string Code { get; set; }
    public required string Name { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CourseCatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Code = "CS", Name = "Computer Science" },
        new() { Code = "MATH", Name = "Mathematics" },
        new() { Code = "ENG", Name = "English" },
        new() { Code = "PHYS", Name = "Physics" },
        new() { Code = "HIST", Name = "History" },
    ];

    private readonly List<Course> _courses =
    [
        new()
        {
            Id = 1, Code = "CS 101", Title = "Introduction to Computer Science",
            Description = "A foundational course covering computational thinking, basic algorithms, and an introduction to programming using Python. Students will learn problem-solving strategies applicable across disciplines.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentCode = "CS",
            InstructorName = "Dr. Ada Lovelace", InstructorBio = "Dr. Lovelace holds a Ph.D. in Computer Science from MIT and has over 15 years of experience teaching introductory computing courses. Her research focuses on CS education and curriculum design.",
            IsFeatured = true
        },
        new()
        {
            Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms",
            Description = "Study of fundamental data structures including arrays, linked lists, trees, graphs, and hash tables. Covers algorithm analysis, sorting, searching, and graph algorithms.",
            Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", DepartmentCode = "CS",
            InstructorName = "Dr. Alan Turing", InstructorBio = "Dr. Turing is a professor of Computer Science specializing in algorithms and computational complexity. He has published extensively in top-tier journals and conferences.",
            IsFeatured = true
        },
        new()
        {
            Id = 3, Code = "CS 310", Title = "Database Systems",
            Description = "Introduction to database design, relational algebra, SQL, normalization, transaction processing, and an overview of NoSQL databases.",
            Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", DepartmentCode = "CS",
            InstructorName = "Dr. Edgar Codd", InstructorBio = "Dr. Codd brings two decades of industry and academic experience in data management. He previously worked as a database architect at a Fortune 500 company.",
            IsFeatured = false
        },
        new()
        {
            Id = 4, Code = "MATH 101", Title = "Calculus I",
            Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.",
            Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentCode = "MATH",
            InstructorName = "Dr. Emmy Noether", InstructorBio = "Dr. Noether is a distinguished professor of Mathematics with research interests in abstract algebra and theoretical physics. She is a recipient of the university's Excellence in Teaching award.",
            IsFeatured = true
        },
        new()
        {
            Id = 5, Code = "MATH 201", Title = "Linear Algebra",
            Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations. Applications in data science and engineering.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", DepartmentCode = "MATH",
            InstructorName = "Dr. Carl Gauss", InstructorBio = "Dr. Gauss is an associate professor specializing in numerical analysis and applied mathematics. He emphasizes intuitive understanding and real-world applications.",
            IsFeatured = false
        },
        new()
        {
            Id = 6, Code = "ENG 101", Title = "English Composition",
            Description = "Developing clear, effective writing through essays, research papers, and critical analysis. Focus on argumentation, evidence, and revision.",
            Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentCode = "ENG",
            InstructorName = "Prof. Virginia Woolf", InstructorBio = "Prof. Woolf is an award-winning author and writing instructor. She has taught composition and creative writing for over 12 years and mentors students in the university writing center.",
            IsFeatured = false
        },
        new()
        {
            Id = 7, Code = "ENG 220", Title = "American Literature",
            Description = "A survey of American literary works from the colonial period to the present, examining themes of identity, democracy, and social change.",
            Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", DepartmentCode = "ENG",
            InstructorName = "Dr. Mark Twain", InstructorBio = "Dr. Twain is a professor of English Literature with a specialty in 19th-century American fiction. He is known for his engaging lecture style and deep knowledge of literary history.",
            IsFeatured = true
        },
        new()
        {
            Id = 8, Code = "PHYS 101", Title = "General Physics I",
            Description = "Mechanics, thermodynamics, and waves. Includes laboratory sessions with hands-on experiments and data analysis.",
            Credits = 4, Schedule = "Mon/Wed 8:00–9:20 AM, Lab Fri 1:00–3:50 PM", DepartmentCode = "PHYS",
            InstructorName = "Dr. Marie Curie", InstructorBio = "Dr. Curie is a research professor of Physics with expertise in experimental physics. She has received multiple grants for her work in materials science.",
            IsFeatured = false
        },
        new()
        {
            Id = 9, Code = "PHYS 205", Title = "Modern Physics",
            Description = "Introduction to special relativity, quantum mechanics, atomic structure, and nuclear physics. Builds on General Physics I and Calculus I.",
            Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", DepartmentCode = "PHYS",
            InstructorName = "Dr. Richard Feynman", InstructorBio = "Dr. Feynman is renowned for his ability to explain complex physics concepts in an accessible way. His research spans quantum electrodynamics and particle physics.",
            IsFeatured = true
        },
        new()
        {
            Id = 10, Code = "HIST 101", Title = "World History to 1500",
            Description = "A global survey of human civilizations from prehistory through the late medieval period, covering social, political, and cultural developments.",
            Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", DepartmentCode = "HIST",
            InstructorName = "Dr. Herodotus Smith", InstructorBio = "Dr. Smith is a historian specializing in ancient and medieval civilizations. He has led archaeological field studies and published two books on cross-cultural exchange in the ancient world.",
            IsFeatured = false
        },
        new()
        {
            Id = 11, Code = "HIST 250", Title = "The Modern World",
            Description = "Major events and movements from the Enlightenment to the present, including industrialization, world wars, decolonization, and globalization.",
            Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", DepartmentCode = "HIST",
            InstructorName = "Dr. Eleanor Roosevelt", InstructorBio = "Dr. Roosevelt is a professor of Modern History with a focus on 20th-century diplomacy and human rights. She frequently contributes commentary to academic journals and public media.",
            IsFeatured = false
        },
    ];

    public IReadOnlyList<Department> GetDepartments() => _departments;

    public IReadOnlyList<Course> GetAllCourses() => _courses;

    public IReadOnlyList<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, string? departmentCode)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentCode))
        {
            query = query.Where(c => c.DepartmentCode.Equals(departmentCode, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            query = query.Where(c =>
                c.Title.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(searchTerm, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(searchTerm, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourseById(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public Department? GetDepartment(string code) =>
        _departments.FirstOrDefault(d => d.Code.Equals(code, StringComparison.OrdinalIgnoreCase));

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId)
            && request.CourseId > 0
            && _courses.Any(c => c.Id == request.CourseId);
    }
}

